/* Lisa's Island - smoke for Lisa's little lessons (Node Playwright, Firefox, touch, file://).
   Run: node tools/smoke_lesson.js [--dev]
   --dev uses tools/lesson_dev.html (generated by tools/lesson_dev_gen.py) instead of app/index.html (only needed before index.html carries the lesson files).
   Plays all 11 combined lessons fast through UI.screens.lesson at 1128x752 and 1920x1080: taps one prediction (each prompt), checks the question repeats once on idle,
   no console errors, onDone fired, save updated, 2 outcome tiles per prompt, tiles are real taps; screenshots tools/shots/lesson_<id>_<beat>_<w>.png.
   smoke.js wipes tools/shots, so run the whole chain in order: smoke.js, smoke_scene.js, smoke_mg.js, smoke_house.js, smoke_lesson.js. */
const path = require('path');
const { boot, sleep, SHOTS, ROOT } = require('./mg_lib');

const DEV = process.argv.includes('--dev');
const URL = 'file://' + path.join(ROOT, DEV ? 'tools/lesson_dev.html' : 'app/index.html');
const VIEWPORTS = [{ width: 1128, height: 752 }, { width: 1920, height: 1080 }];
const HISTORY = ['hist_castle', 'hist_tiles', 'hist_tram', 'hist_ship', 'hist_doll', 'hist_print'];
const SHOT_BEATS = { float: { 0: 'start', 3: 'logfloats', 5: 'keysinks', 7: 'recap' }, daynight: { 0: 'morning', 1: 'noon', 4: 'night', 6: 'badges' }, stones: { 0: 'start', 1: 'count', 4: 'hop', 5: 'across' }, repka: { 0: 'plant', 3: 'helpers', 5: 'pull', 6: 'count' }, more: { 0: 'baskets', 1: 'three-one', 5: 'equal', 6: 'summary' },
  hist_castle:{0:'start',3:'prompt',4:'reveal'},hist_tiles:{0:'start',3:'prompt',4:'reveal'},hist_tram:{0:'start',3:'prompt',4:'reveal'},hist_ship:{0:'start',3:'prompt',4:'reveal'},hist_doll:{0:'start',2:'prompt',3:'reveal'},hist_print:{0:'start',3:'prompt',4:'reveal'} };
const waitPromptFree = (lib, timeout = 22000) => lib.page.waitForFunction(() => !document.querySelector('.prompt-playing, .prompt-choice') && !(window.__test && __test.quizBusy && __test.quizBusy()), null, { timeout });
const lt = (lib) => lib.page.evaluate(() => (window.__lessonTest ? __lessonTest.state() : null));
/* One browser turn binds state and basket evidence to this exact mounted scene. */
function lessonObservation() {
  const owner = window.__lessonSmokeOwner, current = window.__lessonTest;
  if (!owner || current !== owner || !owner.S || !owner.S.box || !owner.S.box.isConnected) return { state: null, basketCounts: null };
  const state = owner.state();
  if (state.id !== owner.id) return { state: null, basketCounts: null };
  let basketCounts = null;
  if (owner.id === 'more' && state.beat === 6 && state.phase === 'beat') {
    const left = owner.S.box.querySelector('.ls-more-left'), right = owner.S.box.querySelector('.ls-more-right');
    if (left && right) basketCounts = [left.dataset.count, right.dataset.count];
  }
  let repkaWitness = null;
  if (owner.id === 'repka' && state.beat === 6 && state.phase === 'beat') {
    const joined = [...owner.S.box.querySelectorAll('.ls-actors .ls-a[data-helper]')].filter(n => n.dataset.joined === 'true').map(n => n.dataset.helper);
    repkaWitness = { joined, extracted: !!owner.S.box.querySelector('.ls-rp-turnip[data-extracted="true"]') };
  }
  return { state, basketCounts, repkaWitness };
}


async function playLesson(lib, id, vp, firstRun) {
  const { page, expect } = lib;
  const tag = id + '_%B_' + vp.width;
  const shot = (b) => page.screenshot({ path: path.join(SHOTS, 'lesson_' + tag.replace('%B', b) + '.png') });
  await page.evaluate(() => { Core.curLang && 0; });
  const before = await page.evaluate((i) => Lesson.seen(Core.curLang(), i), id);
  await page.evaluate(() => { window.__lessonSpeechLog=[]; window.__lessonSpeechOriginal=Core.Snd.say; Core.Snd.say=function(list){ window.__lessonSpeechLog.push(Array.from(list||[])); return window.__lessonSpeechOriginal.apply(this,arguments); }; });
  await page.evaluate((i) => { window.__done = null; __test.go('lesson', { id: i, done: () => { window.__done = true; __test.go('home'); } }); window.__lessonSmokeOwner = window.__lessonTest; }, id);
  try {
  await page.waitForFunction(() => window.__lessonTest, null, { timeout: 8000 }).catch(() => lib.fail(id + ': lesson did not start'));
  const t0 = Date.now(); let lastBeat = -1, shots = {}, pickedPrompts = 0, moreWitness = false, repkaWitness = false;
  const want = SHOT_BEATS[id];            /* beat index -> shot name, taken ~0.6 s (real) into that beat */
  while (Date.now() - t0 < 120000) {
    const observation = await page.evaluate(lessonObservation), s = observation.state;
    if (!s) break;
    if (observation.basketCounts && observation.basketCounts.join() === '3,3') moreWitness = true;
    if (observation.repkaWitness && ['grandpa','grandma','girl','dog','cat','mouse'].every(n => observation.repkaWitness.joined.includes(n)) && observation.repkaWitness.extracted) repkaWitness = true;
    if (s.beat !== lastBeat) { lastBeat = s.beat; if (want[s.beat] && s.phase === 'beat') { await sleep(600); await shot(want[s.beat]); } }
    if (s.phase === 'prompt') {
      if (!shots.prompt) { await sleep(500); await shot('prompt'); shots.prompt = 1; }
      const n = await page.evaluate(() => document.querySelectorAll('.ls-tile').length);
      expect(n === 2, id + ': a prompt needs exactly 2 outcome tiles, got ' + n);
      await page.waitForFunction(() => new Promise((resolve) => {
        const started = performance.now();
        let previousWidth;
        const check = () => {
          const el = document.querySelector('.ls-tile');
          if (!el || performance.now() - started >= 3000) return resolve(false);
          const running = el.getAnimations({ subtree: true }).some((animation) => animation.playState === 'running');
          const width = el.getBoundingClientRect().width;
          if (!running && previousWidth === width) return resolve(true);
          previousWidth = width;
          requestAnimationFrame(check);
        };
        requestAnimationFrame(check);
      }), null, { timeout: 3000 }).catch(() => {});
      const r = await page.evaluate(() => { const t = document.querySelector('.ls-tile').getBoundingClientRect(); const e = document.elementFromPoint(t.left + t.width / 2, t.top + t.height / 2); return { w: t.width, h: t.height, hit: !!(e && e.closest('.ls-tile')) }; });
      expect(r.w >= 150 && (id !== 'repka' && id !== 'more' || r.h >= 110) && r.hit, id + ': tile too small or not tappable ' + JSON.stringify(r));
      const wanted = id === 'repka' ? (vp.width === 1128 ? 'cat' : 'mouse') : id === 'more' ? (vp.width === 1128 ? 'small' : 'large') : id === 'hist_castle' ? (vp.width === 1128 ? 'tower' : 'wall') : id === 'hist_ship' ? (vp.width === 1128 ? 'sailA' : 'sailB') : id === 'hist_tiles' && vp.width === 1920 ? 'other' : id === 'hist_tiles' ? 'match' : id === 'hist_tram' ? (vp.width === 1128 ? 'yes' : 'no') : id === 'hist_print' ? (vp.width === 1128 ? 'page' : 'letters') : id === 'hist_doll' ? (vp.width === 1128 ? 'inside' : 'outside') : null;
      const c = await page.evaluate((choice) => { const t = choice ? document.querySelector('.ls-tile[data-choice="'+choice+'"]') : document.querySelector('.ls-tile'); const r=t.getBoundingClientRect(); return { x:r.left+r.width/2,y:r.top+r.height/2,choice:t.dataset.choice }; }, wanted);
      await waitPromptFree(lib);
      await page.touchscreen.tap(c.x, c.y); pickedPrompts++;
      await sleep(200); const s2 = await lt(lib);
      expect(s2.picks.length === pickedPrompts && !s2.picks[pickedPrompts - 1].auto, id + ': the tap was not recorded ' + JSON.stringify(s2.picks));
      if (wanted) expect(s2.picks[pickedPrompts - 1].choice === wanted, id + ': selected picture identity changed after shuffle ' + JSON.stringify(s2.picks));
      if (pickedPrompts === 1) await shot('picked');
      await sleep(600);
      continue;
    }
    if (id === 'repka' && s.beat === 5) await page.waitForFunction(() => document.querySelector('.ls-rp-turnip[data-extracted="true"]'), null, { timeout: 8000 });
    if (id === 'repka' && s.beat === 6 && s.phase === 'beat') {
      const state = observation.repkaWitness;
      expect(!!state, 'repka: original-scene extraction witness required');
      expect(['grandpa','grandma','girl','dog','cat','mouse'].every(n => state.joined.includes(n)) && state.extracted, 'repka: all helpers joined before the turnip was extracted ' + JSON.stringify(state));
    }
    if (id === 'more' && s.beat === 6 && s.phase === 'beat') {
      const counts = observation.basketCounts;
      expect(!!counts && counts.join() === '3,3', 'more: both baskets end with three apples ' + (counts ? counts.join() : 'missing original-scene counts'));
    }
    if (s.phase === 'word' && !shots.word) { await page.evaluate(() => { Core.speed = 1; }); await sleep(900); await shot('word'); shots.word = 1; await page.evaluate(() => { Core.speed = 3; }); }
    if (s.done) break;
    await sleep(60);
  }
  await sleep(300);
  const done = await page.evaluate(() => window.__done);
  expect(done === true, id + ': onDone was not called');
  const after = await page.evaluate((i) => Lesson.seen(Core.curLang(), i), id);
  expect(after === before + 1, id + ': save not updated (' + before + ' -> ' + after + ')');
  const rec = await page.evaluate((i) => Core.L(Core.curLang()).lessons[i], id);
  expect(rec && rec.seen === after && rec.last > 0, id + ': bad save record ' + JSON.stringify(rec));
  expect(pickedPrompts === (id === 'float' || id === 'hist_tiles' && vp.width === 1920 ? 2 : 1), id + ': expected prompts, got ' + pickedPrompts);
  if (id === 'repka') expect(repkaWitness, 'repka: required original-scene six-helper extraction witness was not observed');
  if (id === 'more') {
    expect(moreWitness, 'more: required original-scene final 3,3 witness was not observed');
    const audit=await page.evaluate(()=>window.__lessonSpeechLog.flat().map(String));
    const reply=audit.findIndex(url=>url.includes('ru_cs_more_count.ogg'));
    const check=audit.findIndex(url=>url.includes('ru_cs_check.ogg'));
    const counting=audit.findIndex(url=>url.includes('ru_cs_more_4.ogg'));
    if (vp.width===1128) expect(reply>=0 && reply<counting && check<0,'more: smaller-basket response plays before counting with no generic check '+JSON.stringify(audit));
    else expect(check>=0 && check<counting && reply<0,'more: larger-basket choice keeps the default response before counting '+JSON.stringify(audit));
  }
  await page.waitForFunction(() => __test.screen() !== 'lesson', null, { timeout: 4000 }).catch(() => lib.fail(id + ': the screen did not close after onDone'));
  } finally {
    await page.evaluate(() => { if(window.__lessonSpeechOriginal) Core.Snd.say=window.__lessonSpeechOriginal; delete window.__lessonSpeechOriginal; delete window.__lessonSmokeOwner; });
  }
}

async function idleCase(lib, vp) {
  /* real-time idle behaviour: pulse + one question repeat at 8 s, auto-continue at 15 s */
  const { page, expect } = lib;
  await page.evaluate(() => { __test.go('lesson', { id: 'daynight' }); });
  await page.waitForFunction(() => window.__lessonTest, null, { timeout: 8000 });
  await page.waitForFunction(() => __lessonTest.state().phase === 'prompt', null, { timeout: 60000 }).catch(() => lib.fail('idle: no prompt reached'));
  await sleep(3600);   /* 3x speed: 8 s virtual = 2.7 s real */
  const s = await lt(lib);
  expect(s && s.pulsed && s.repeated, 'idle: no pulse + repeat after 8 s ' + JSON.stringify(s && { p: s.pulsed, r: s.repeated }));
  await sleep(2800);
  const s2 = await lt(lib);
  expect(s2 && s2.picks.length === 1 && s2.picks[0].auto, 'idle: no auto-continue after 15 s ' + JSON.stringify(s2 && s2.picks));
  await page.evaluate(() => { __test.go('home'); });
  await sleep(300);
}

async function earlyExitCase(lib) {
  const {page,expect}=lib;
  const before=await page.evaluate(()=>Lesson.seen(Core.curLang(),'more'));
  await page.evaluate(()=>__test.go('lesson',{id:'more'}));
  await page.waitForFunction(()=>window.__lessonTest&&__lessonTest.id==='more',null,{timeout:8000});
  await page.waitForFunction(()=>__lessonTest.state().phase==='prompt',null,{timeout:60000});
  await lib.tapSel('.ls-bar .b-back');
  await page.waitForFunction(()=>__test.screen()==='home',null,{timeout:8000});
  await sleep(250);
  const result=await page.evaluate(()=>({screen:__test.screen(),hook:!!window.__lessonTest,seen:Lesson.seen(Core.curLang(),'more')}));
  expect(result.screen==='home'&&!result.hook&&result.seen===before,'early exit: destroys scene and does not record completion '+JSON.stringify(result));
  await page.evaluate(()=>__test.go('home'));
}

if (require.main === module) (async () => {
  let code = 0;
  for (const vp of VIEWPORTS) {
    console.log('viewport ' + vp.width + 'x' + vp.height);
    const lib = await boot({ viewport: vp, url: URL, speed: 3 });
    try {
      for (const id of ['float', 'daynight', 'stones', 'repka', 'more', ...HISTORY]) { console.log('  lesson ' + id); await playLesson(lib, id, vp, true); }
      if (vp.width === 1128) await idleCase(lib, vp);
      if (vp.width === 1128) await earlyExitCase(lib);
      const fs = require('fs');
      for (const id of ['float', 'daynight', 'stones', 'repka', 'more', ...HISTORY]) {
        const n = fs.readdirSync(SHOTS).filter((f) => f.startsWith('lesson_' + id + '_') && f.endsWith('_' + vp.width + '.png')).length;
        lib.expect(n >= 3, id + ': need >= 3 screenshots, have ' + n);
      }
    } catch (e) { lib.fail('exception: ' + (e && e.stack || e)); }
    code = (await lib.finish('LESSON SMOKE ' + vp.width)) || code;
  }
  process.exit(code);
})();

module.exports = { playLesson, lessonObservation };
